// UI for the isolated art prototype; no production API or account data is mutated.
export const mealUI=(saved,date,esc)=>{
 const rows=saved.meals.filter(m=>m.date===date),spend=rows.reduce((a,b)=>a+Number(b.cost||0),0),cal=rows.reduce((a,b)=>a+Number(b.calories||0),0);
 const days=Array.from({length:7},(_,i)=>{const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+i-3);return {key:d.toLocaleDateString('sv-SE'),day:d.getDate(),week:['日','一','二','三','四','五','六'][d.getDay()]}});
 return `<div class="panel-eyebrow">MY EVERYDAY TABLE</div><h2 id="panel-title">今日记餐</h2><div class="day-strip">${days.map(d=>`<button data-day="${d.key}" class="${d.key===date?'active':''}"><small>周${d.week}</small>${d.day}</button>`).join('')}</div><label class="field">日期<input type="date" id="meal-date" class="panel-input" value="${date}"></label><div class="stat-strip"><div><strong>${rows.length}</strong><small>餐记录</small></div><div><strong>¥${spend.toFixed(0)}</strong><small>当天花费</small></div><div><strong>${cal||'—'}</strong><small>已记千卡</small></div></div><form id="meal-form"><div class="chips">${['早餐','午餐','晚餐','加餐'].map(t=>`<button type="button" class="panel-chip" data-mealtype="${t}" aria-pressed="${t==='晚餐'}">${t}</button>`).join('')}</div><label class="field">吃了什么<input name="name" class="panel-input" placeholder="今天的这一餐" required maxlength="40"></label><div class="form-pair"><label class="field">怎么吃<select name="dining" class="panel-input"><option>在家做</option><option>在外吃</option><option>外卖</option></select></label><label class="field">花费 · 元<input name="cost" type="number" min="0" max="10000" step=".01" value="18" class="panel-input"></label></div><details class="fold"><summary>照片、热量与评分</summary><label class="field">餐食照片<input type="file" accept="image/*" id="meal-photo" class="panel-input"></label><img id="meal-photo-preview" class="compose-photo" hidden alt="待保存餐食照片"><div class="form-pair"><label class="field">热量 · 千卡<input name="calories" class="panel-input" type="number" min="0" max="10000" placeholder="可不填"></label><label class="field">味道<select name="rating" class="panel-input"><option value="0">还没评分</option><option value="5">超喜欢 ★★★★★</option><option value="4">好吃 ★★★★</option><option value="3">还行 ★★★</option><option value="2">一般 ★★</option><option value="1">不喜欢 ★</option></select></label></div></details><button class="panel-primary" type="submit">记下这一餐</button></form><h3>${date.slice(5).replace('-','月')}日的餐桌</h3><div id="meal-list">${rows.length?rows.slice().reverse().map(m=>`<article class="journal-meal">${m.photo?`<img src="${m.photo}" alt="餐食">`:''}<div class="meal-card"><span>${esc(m.type)} · ${esc(m.name)}<br><small>${esc(m.dining)}${m.rating?' · '+'★'.repeat(m.rating):''}</small></span><span>¥${m.cost}</span></div></article>`).join(''):'<div class="empty-illustration"><img src="/media/brand_monster.png" alt="抱着饭碗的小怪"><p>这一天的餐桌，等你添一笔。</p></div>'}</div>`;
};
export const pantryUI=(zone='全部')=>{const stock=[['🥬','小白菜','冷藏 · 1把','优先吃','冷藏'],['🥚','鸡蛋','冷藏 · 6个','找搭配','冷藏'],['🍅','番茄','冷藏 · 3个','找搭配','冷藏'],['🍚','大米','常温 · 2千克','看看做法','常温'],['🍗','鸡肉','冷冻 · 400克','找搭配','冷冻']];return `<div class="panel-eyebrow">A PANTRY OF POSSIBILITIES</div><h2 id="panel-title">我的冰箱</h2><p class="section-note">示例食材 · 点食材找做法</p><div class="chips">${['全部','冷藏','冷冻','常温'].map(z=>`<button data-zone="${z}" class="panel-chip" aria-pressed="${z===zone}">${z}</button>`).join('')}</div>${stock.filter(s=>zone==='全部'||s[4]===zone).map(([e,n,s,t])=>`<div class="stock-row"><span class="stock-dot">${e}</span><div><strong>${n}</strong><small>${s}</small></div><button class="panel-chip" data-ingredient="${n}">${t}</button></div>`).join('')}<div class="chips"><button class="panel-chip" data-stock-view="history">消耗记录 ↗</button><button class="panel-chip" data-station="shopping">采购小篮 ↗</button></div><div id="stock-history" hidden><h3>最近消耗 · 示例</h3><div class="meal-card"><span>鸡蛋 · 用了 2 个<br><small>上次购入 10 个 · ¥12</small></span><span>昨天</span></div><div class="meal-card"><span>番茄 · 用了 1 个<br><small>上次购入 500克 · ¥6</small></span><span>前天</span></div></div>`};
export const communityUI=(saved,catalog,image,esc)=>{
 const posts=[...(saved.posts||[]).map((p,i)=>({...p,id:'local'+i,author:saved.nickname||'我的小怪',local:true})),{id:'sample1',author:'住在春天里',text:'下班后的十五分钟，留给番茄炒蛋。',photo:image(catalog.find(r=>r.name==='番茄炒蛋')||catalog[0]),likes:23},{id:'sample2',author:'不想洗碗的小厨',text:'用一锅汤，把周末煮得暖暖的。',photo:image(catalog.find(r=>/汤/.test(r.name))||catalog[1]),likes:18}];
 return `<div class="panel-eyebrow">AT THE SAME TABLE</div><h2 id="panel-title">餐桌广场</h2><p class="section-note">美术预览 · 以下为示例分享，发布仅保存在本页</p><details class="fold"><summary>＋ 分享我的这一餐</summary><form id="post-form"><label class="field">想说的话<textarea name="text" class="panel-input" maxlength="300" rows="3" required placeholder="今天吃到了什么好味道？"></textarea></label><label class="field">配一张照片<input type="file" accept="image/*" id="post-photo" class="panel-input"></label><img id="post-photo-preview" class="compose-photo" hidden alt="待发布照片"><button class="panel-primary">发布到本页广场</button></form></details>${posts.map(p=>`<article class="community-post"><small>${p.local?'本页发布':'示例'} · ${esc(p.author)}</small><p>${esc(p.text)}</p>${p.photo?`<img class="post-photo" src="${p.photo}" alt="${p.local?'用户餐食照片':'示例菜品插画'}">`:''}<div class="post-actions"><small>${p.local?'刚刚':'今天'}</small><button data-like-post="${p.id}" aria-pressed="${(saved.likedPosts||[]).includes(p.id)}">${(saved.likedPosts||[]).includes(p.id)?'♥':'♡'} ${(p.likes||0)+((saved.likedPosts||[]).includes(p.id)?1:0)}</button></div></article>`).join('')}`
};
export const profileUI=(saved,mode,catalog,mini,esc)=>`<div class="panel-eyebrow">YOUR LITTLE CORNER</div><h2 id="panel-title">我的小怪</h2><div class="profile-row"><img src="/media/brand_monster.png" alt="小怪"><div><strong>${esc(saved.nickname||'今天也开饭')}</strong><small>本地体验档案</small></div></div><div class="stat-strip"><div><strong>${saved.meals.length}</strong><small>餐记录</small></div><div><strong>${saved.favorites.length}</strong><small>道喜欢</small></div><div><strong>${(saved.posts||[]).length}</strong><small>篇分享</small></div></div><details class="fold"><summary>编辑我的偏好</summary><label class="field">昵称<input id="nickname" class="panel-input" value="${esc(saved.nickname||'今天也开饭')}" maxlength="20"></label><div class="setting-group"><label class="setting-row">日常方式<select id="dining-pref"><option ${saved.diningPref==='自己做饭'?'selected':''}>自己做饭</option><option ${saved.diningPref==='在外吃 / 外卖'?'selected':''}>在外吃 / 外卖</option></select></label><label class="setting-row">口味<select id="taste-pref">${['均衡','清淡','香辣'].map(t=>`<option ${saved.tastePref===t?'selected':''}>${t}</option>`).join('')}</select></label></div><button class="panel-primary" id="save-profile">保存偏好</button></details><h3>显示方式</h3><div class="mode-choice"><button data-mode="3d" class="${mode==='3d'?'active':''}">3D 小屋</button><button data-mode="simple" class="${mode==='simple'?'active':''}">简洁模式</button></div><h3>喜欢的菜</h3>${catalog.filter(r=>saved.favorites.includes(r.id)).map(mini).join('')||'<p class="section-note">点亮一颗红心，留住下一餐的灵感。</p>'}`;
